using System;using System.IO;using System.Text;using System.Collections.Generic;
// CN notify105 fields verified at466010. TW70 dispatcher reads space+slot;
// the current CN outgoing hatch writer still needs real-window confirmation.
class Offline70PetFG96 {
 internal static bool IsEgg(uint id){return id==2681358||id==2747023||id==63145||id==63022;}
 internal static bool IsPet(uint id){return id==2681359||id==2747024||id==63146||id==63023;}
 internal static uint Hatched(uint id){if(id==2681358)return 2681359;if(id==2747023)return 2747024;if(id==63145)return 63146;if(id==63022)return 63023;throw new InvalidDataException("Unreviewed creature egg");}
 internal static void Validate(Offline70EconomyState s){
  if(s.NextCreatureKey<2||s.NextCreatureKey>Int32.MaxValue)throw new InvalidDataException("Creature serial capacity");HashSet<uint> ids=new HashSet<uint>();
  foreach(Offline70EconomyEntry e in s.Inventory){bool pet=IsPet(e.ItemId),egg=IsEgg(e.ItemId);if(pet){if(!(e.List==7||e.List==3&&e.Slot==22)||e.Quantity!=1||e.CreatureKey<2||e.CreatureKey>=s.NextCreatureKey||!Offline70PetExperienceFG109.Valid(e)||e.CreatureSatiety>100||e.CreatureFeedUtcTicks<0||e.CreatureFeedUtcTicks>DateTime.MaxValue.Ticks||!ids.Add(e.CreatureKey)||e.CreatureName==null||Encoding.GetEncoding(936).GetByteCount(e.CreatureName)>=30||e.CreatureName.IndexOf('\0')>=0)throw new InvalidDataException("Creature instance profile");foreach(char c in e.CreatureName)if(Char.IsControl(c))throw new InvalidDataException("Creature name control");}
   else if(e.CreatureKey!=0||e.CreatureExperience!=0||e.CreatureLevel!=0||e.CreatureSatiety!=0||e.CreatureFeedUtcTicks!=0||!String.IsNullOrEmpty(e.CreatureName))throw new InvalidDataException("Non-creature detail fields");
   if(Offline70Economy.Definition(e.ItemId).Kind==6&&!pet&&!egg)throw new InvalidDataException("Unreviewed pet item profile");
  }
 }
 internal static ushort ParseHatch(byte[] encrypted,byte[] keys){if(encrypted==null||encrypted.Length!=8)throw new InvalidDataException("Creature hatch request bounds");byte[] b=Offline70RoleProtocol.BatchCryptFG(encrypted,keys,7,false);if(b[0]!=7)throw new InvalidDataException("Creature hatch item space");ushort slot=BitConverter.ToUInt16(b,1);if(slot>=140)throw new InvalidDataException("Creature hatch slot");for(int i=3;i<8;i++)if(b[i]!=0)throw new InvalidDataException("Creature hatch padding");return slot;}
 internal static Offline70EconomyState Hatch(string path,string receipt,ushort slot,out bool duplicate){if(slot>=140)throw new InvalidDataException("Creature hatch slot bounds");return Offline70Economy.Apply(path,receipt,"pet-hatch","7:"+slot,delegate(Offline70EconomyState s){Offline70EconomyEntry e=Offline70Economy.Find(s,7,slot);if(e==null||!IsEgg(e.ItemId)||e.Quantity!=1||e.CreatureKey!=0||s.NextCreatureKey>=Int32.MaxValue)throw new InvalidDataException("Creature hatch ownership");e.ItemId=Hatched(e.ItemId);e.CreatureKey=s.NextCreatureKey++;e.CreatureExperience=0;e.CreatureLevel=1;e.CreatureSatiety=100;e.CreatureName=String.Empty;e.Sealed=false;},out duplicate);}
 internal static byte[] DetailsBody(Offline70EconomyState s,uint only){Offline70Economy.Validate(s);List<Offline70EconomyEntry> rows=new List<Offline70EconomyEntry>();foreach(Offline70EconomyEntry e in s.Inventory)if(IsPet(e.ItemId)&&(only==0||e.CreatureKey==only))rows.Add(e);rows.Sort(delegate(Offline70EconomyEntry a,Offline70EconomyEntry b){return a.CreatureKey.CompareTo(b.CreatureKey);});if(only!=0&&rows.Count!=1||rows.Count>141)throw new InvalidDataException("Creature detail selection");using(MemoryStream m=new MemoryStream())using(BinaryWriter w=new BinaryWriter(m)){w.Write((byte)rows.Count);foreach(Offline70EconomyEntry e in rows){w.Write(e.CreatureKey);w.Write(e.CreatureSatiety);w.Write(e.CreatureExperience);w.Write(e.CreatureLevel);byte[] name=Encoding.GetEncoding(936).GetBytes(e.CreatureName);w.Write((uint)name.Length);w.Write(name);w.Write((byte)0);}return m.ToArray();}}
 internal static byte[] DetailsReply(Offline70EconomyState s,uint only,byte[] keys){return Offline70RoleProtocol.BatchPacketFG(0,105,DetailsBody(s,only),keys,false);}
 internal static byte[] HatchAck(bool success,byte[] keys){return Offline70RoleProtocol.BatchPacketFG(1,105,success?new byte[]{1}:new byte[]{0,0x17},keys,false);}
 internal static byte[] ItemBody(Offline70EconomyEntry e){if(e==null||e.List!=7||!IsPet(e.ItemId))throw new InvalidDataException("Hatched item projection");byte[] b=new byte[34];b[0]=7;b[1]=1;Offline70EconomyProtocol.InventoryRow(e).CopyTo(b,3);return b;}
}
partial class Offline70BatchServiceFG {
 readonly Dictionary<ushort,string> hatchRequestsFG96=new Dictionary<ushort,string>();
 void HatchPetFG96(byte[] encrypted,ushort sequence){string fingerprint=Convert.ToBase64String(encrypted),prior;if(hatchRequestsFG96.TryGetValue(sequence,out prior)){if(prior!=fingerprint)throw new InvalidDataException("Creature hatch sequence reused");Note("CREATURE_HATCH_DUPLICATE_IGNORED");return;}bool success=false;uint serial=0;ushort slot=0;try{if(dungeon.Active)throw new InvalidDataException("Creature hatching currently requires town");slot=Offline70PetFG96.ParseHatch(encrypted,keys);Sync();bool duplicate;assets=Offline70PetFG96.Hatch(economyPath,session+"-pet-hatch-"+sequence,slot,out duplicate);Offline70EconomyEntry e=Offline70Economy.Find(assets,7,slot);serial=e.CreatureKey;success=true;Note("CREATURE_HATCH_COMMITTED slot="+slot+" item="+e.ItemId+" serial="+serial+" duplicate="+duplicate);}catch(InvalidDataException e){Note("CREATURE_HATCH_REJECTED "+e.Message);}hatchRequestsFG96.Add(sequence,fingerprint);Send(success?"pet-hatched105":"pet-hatch-failed105",Offline70PetFG96.HatchAck(success,keys));if(success){Sync();Send("pet-details105",Offline70PetFG96.DetailsReply(assets,serial,keys));Send("pet-hatched-item14",Offline70EconomyProtocol.UpdatePacket(Offline70PetFG96.ItemBody(Offline70Economy.Find(assets,7,slot)),keys));}}
}
